  int val;
  Node* next;
};
int main() {
  Node* head = nullptr;
  for (int i = 1; i <= 3; i++) {
    Node* n = new Node();
    n->val = i * 10;
    n->next = head;
    head = n;
  }
  for (Node* p = head; p != nullptr; p = p->next) cout << p->val << " ";
  cout << endl;
  return 0;
}
